<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/ProductionContext.php';
require_once __DIR__.'/VolunteerAutomationService.php';

final class VolunteerDevelopmentExperience
{
    private const ROUTES=['/volunteer/history','/volunteer/training','/admin/volunteer-development'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();
        $db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['volunteer_development_csrf']??=bin2hex(random_bytes(24));
        if($route==='/admin/volunteer-development'&&!AccessPolicy::canManageVolunteers($user))self::forbidden();
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$route,$basePath);
        self::page($db,$route,$basePath,$user);
    }

    private static function handlePost(PDO $db,array $user,string $route,string $basePath):never
    {
        if(!hash_equals((string)($_SESSION['volunteer_development_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired. Please try again.');self::redirect($basePath.$route);}
        if(!AccessPolicy::canManageVolunteers($user))self::forbidden();$action=(string)($_POST['action']??'');
        try{
            if($action==='save_training'){
                $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$instructions=trim((string)($_POST['completion_instructions']??''));$requirementId=filter_input(INPUT_POST,'requirement_id',FILTER_VALIDATE_INT)?:null;$validity=filter_input(INPUT_POST,'validity_days',FILTER_VALIDATE_INT)?:null;
                if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a training title up to 190 characters.');if($validity!==null&&$validity<1)throw new RuntimeException('Validity days must be positive.');
                $db->beginTransaction();$stmt=$db->prepare('INSERT INTO volunteer_training_modules (requirement_id,title,description,completion_instructions,validity_days,active,created_by_user_id) VALUES (:requirement,:title,:description,:instructions,:validity,1,:actor)');$stmt->execute(['requirement'=>$requirementId,'title'=>$title,'description'=>$description!==''?$description:null,'instructions'=>$instructions!==''?$instructions:null,'validity'=>$validity,'actor'=>(int)$user['id']]);$id=(int)$db->lastInsertId();self::audit($db,(int)$user['id'],'volunteer.training_created','volunteer_training_module',$id,'Created volunteer training module.',['requirement_id'=>$requirementId,'validity_days'=>$validity]);$db->commit();self::flash('success','Training module created.');
            } elseif($action==='verify_training'){
                $moduleId=filter_input(INPUT_POST,'module_id',FILTER_VALIDATE_INT)?:0;$userId=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;if($moduleId<1||$userId<1)throw new RuntimeException('Choose a training module and volunteer.');$db->beginTransaction();VolunteerAutomationService::completeTraining($db,$moduleId,$userId,(int)$user['id'],trim((string)($_POST['note']??''))?:null);self::audit($db,(int)$user['id'],'volunteer.training_verified','user',$userId,'Verified volunteer training completion.',['module_id'=>$moduleId]);$db->commit();self::flash('success','Training completion verified and readiness updated.');
            } elseif($action==='manual_hours'){
                $userId=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;$hours=(float)($_POST['hours']??0);$served=trim((string)($_POST['served_at']??''));$note=trim((string)($_POST['note']??''));if($userId<1||$hours<=0||$hours>24)throw new RuntimeException('Choose a volunteer and enter up to 24 hours.');$when=DateTimeImmutable::createFromFormat('Y-m-d',$served);if(!$when)throw new RuntimeException('Choose the service date.');$production=ProductionContext::selected($db,$user);$db->beginTransaction();$stmt=$db->prepare("INSERT INTO volunteer_hour_entries (user_id,production_id,shift_id,minutes,source_type,status,note,verified_by_user_id,served_at) VALUES (:user,:production,NULL,:minutes,'manual','verified',:note,:actor,:served)");$stmt->execute(['user'=>$userId,'production'=>$production?(int)$production['id']:null,'minutes'=>(int)round($hours*60),'note'=>$note!==''?$note:null,'actor'=>(int)$user['id'],'served'=>$when->format('Y-m-d 12:00:00')]);$id=(int)$db->lastInsertId();self::audit($db,(int)$user['id'],'volunteer.hours_added','volunteer_hour_entry',$id,'Added verified volunteer service hours.',['user_id'=>$userId,'minutes'=>(int)round($hours*60),'production_id'=>$production?(int)$production['id']:null]);$db->commit();self::flash('success','Volunteer hours added.');
            } elseif($action==='map_form'){
                $formId=filter_input(INPUT_POST,'form_id',FILTER_VALIDATE_INT)?:0;$requirementId=filter_input(INPUT_POST,'requirement_id',FILTER_VALIDATE_INT)?:0;$validity=filter_input(INPUT_POST,'validity_days',FILTER_VALIDATE_INT)?:null;if($formId<1||$requirementId<1)throw new RuntimeException('Choose a form and requirement.');$db->beginTransaction();$stmt=$db->prepare("INSERT INTO form_requirement_mappings (form_id,requirement_id,validity_days,active,created_by_user_id) VALUES (:form,:requirement,:validity,1,:actor) ON DUPLICATE KEY UPDATE validity_days=VALUES(validity_days),active=1,created_by_user_id=VALUES(created_by_user_id),updated_at=CURRENT_TIMESTAMP");$stmt->execute(['form'=>$formId,'requirement'=>$requirementId,'validity'=>$validity,'actor'=>(int)$user['id']]);self::audit($db,(int)$user['id'],'volunteer.form_requirement_mapped','form',$formId,'Mapped approved form to volunteer requirement.',['requirement_id'=>$requirementId,'validity_days'=>$validity]);$db->commit();self::flash('success','Form approval mapping saved.');
            } else throw new RuntimeException('Choose a valid volunteer development action.');
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The volunteer update could not be saved.');}
        self::redirect($basePath.'/admin/volunteer-development');
    }

    private static function page(PDO $db,string $route,string $basePath,array $user):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$staff=AccessPolicy::canManageVolunteers($user);$uid=(int)$user['id'];
        $history=self::hours($db,$uid);$total=VolunteerAutomationService::totalMinutes($db,$uid);$training=self::trainingForUser($db,$uid);$requirements=self::requirements($db);
        $users=$staff?self::volunteers($db):[];$forms=$staff?self::forms($db):[];$modules=$staff?self::modules($db):[];$mappings=$staff?self::mappings($db):[];
        $title=$route==='/volunteer/history'?'Volunteer history':($route==='/volunteer/training'?'Training':'Volunteer development');$subnav=[['label'=>'Readiness','href'=>'/volunteer-readiness','active'=>false],['label'=>'Opportunities','href'=>'/volunteer-shifts','active'=>false],['label'=>'Training','href'=>'/volunteer/training','active'=>$route==='/volunteer/training'],['label'=>'Service record','href'=>'/volunteer/history','active'=>$route==='/volunteer/history'],['label'=>'Verifications','href'=>'/volunteer/verifications','active'=>false]];
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($title)?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/volunteer-development.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Volunteer',$title,$basePath,$subnav);?><div class="vd-page"><?php if($flash):?><div class="vd-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?>
<?php if($route==='/volunteer/history'):?><section class="vd-hero"><div><small>VERIFIED SERVICE</small><h2><?=number_format($total/60,1)?> volunteer hours</h2><p>Completed CTSMD shifts are added automatically when staff marks the roster entry completed. Manual verified service can also be added by staff.</p></div></section><section class="vd-list"><?php if(!$history):?><div class="vd-empty"><b>No verified hours yet.</b></div><?php endif;?><?php foreach($history as $row):?><article><div><small><?=$e(strtoupper($row['source_type']))?> · <?=$e(date('M j, Y',strtotime($row['served_at'])))?></small><h3><?=$e($row['shift_title']?:'Verified service')?></h3><p><?=$e($row['production_title']?:'CTSMD')?><?=$row['note']?' · '.$e($row['note']):''?></p></div><b><?=number_format(((int)$row['minutes'])/60,1)?>h</b></article><?php endforeach;?></section>
<?php elseif($route==='/volunteer/training'):?><section class="vd-hero"><div><small>TRAINING & READINESS</small><h2>Know what is current.</h2><p>Training completion is verified by staff. When a module is linked to a requirement, verification updates your volunteer credential automatically.</p></div></section><section class="vd-grid"><?php if(!$training):?><div class="vd-empty"><b>No active training modules.</b></div><?php endif;?><?php foreach($training as $row):?><article class="vd-training"><small><?=$row['status']==='completed'?'COMPLETED':'AVAILABLE'?></small><h3><?=$e($row['title'])?></h3><p><?=$e((string)$row['description'])?></p><?php if($row['requirement_name']):?><span>Satisfies: <?=$e($row['requirement_name'])?></span><?php endif;?><?php if($row['completed_at']):?><footer>Verified <?=$e(date('M j, Y',strtotime($row['completed_at'])))?></footer><?php endif;?></article><?php endforeach;?></section>
<?php else:?><section class="vd-hero admin"><div><small>VOLUNTEER OPERATIONS</small><h2>Hours, training, and readiness automation.</h2><p>Manage training modules, verify completions, add service hours, and connect approved forms to credentials.</p></div></section><div class="vd-admin-grid"><section class="vd-card"><h3>Create training</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_development_csrf'])?>"><input type="hidden" name="action" value="save_training"><label>Title<input name="title" maxlength="190" required></label><label>Description<textarea name="description" rows="3"></textarea></label><label>Completion instructions<textarea name="completion_instructions" rows="3"></textarea></label><label>Satisfies requirement<select name="requirement_id"><option value="">No automatic credential</option><?php foreach($requirements as $r):?><option value="<?=(int)$r['id']?>"><?=$e($r['name'])?></option><?php endforeach;?></select></label><label>Valid for days<input type="number" min="1" name="validity_days"></label><button class="button" type="submit">Create training</button></form></section><section class="vd-card"><h3>Verify training</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_development_csrf'])?>"><input type="hidden" name="action" value="verify_training"><label>Volunteer<select name="user_id" required><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=$e($u['name'])?></option><?php endforeach;?></select></label><label>Training<select name="module_id" required><?php foreach($modules as $m):?><option value="<?=(int)$m['id']?>"><?=$e($m['title'])?></option><?php endforeach;?></select></label><label>Note<input name="note" maxlength="1000"></label><button class="button" type="submit">Verify completion</button></form></section><section class="vd-card"><h3>Add verified hours</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_development_csrf'])?>"><input type="hidden" name="action" value="manual_hours"><label>Volunteer<select name="user_id" required><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=$e($u['name'])?></option><?php endforeach;?></select></label><label>Hours<input type="number" min="0.25" max="24" step="0.25" name="hours" required></label><label>Date<input type="date" name="served_at" required></label><label>Note<input name="note" maxlength="1000"></label><button class="button" type="submit">Add hours</button></form></section><section class="vd-card"><h3>Form → credential</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_development_csrf'])?>"><input type="hidden" name="action" value="map_form"><label>Approved form<select name="form_id" required><?php foreach($forms as $f):?><option value="<?=(int)$f['id']?>"><?=$e($f['title'])?></option><?php endforeach;?></select></label><label>Requirement<select name="requirement_id" required><?php foreach($requirements as $r):?><option value="<?=(int)$r['id']?>"><?=$e($r['name'])?></option><?php endforeach;?></select></label><label>Valid for days<input type="number" min="1" name="validity_days"></label><button class="button" type="submit">Save mapping</button></form><?php if($mappings):?><div class="vd-mappings"><?php foreach($mappings as $m):?><p><b><?=$e($m['form_title'])?></b><span>→ <?=$e($m['requirement_name'])?><?=$m['validity_days']?' · '.$e((string)$m['validity_days']).' days':''?></span></p><?php endforeach;?></div><?php endif;?></section></div><?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function hours(PDO $db,int $uid):array{$s=$db->prepare("SELECT h.*,vs.title shift_title,p.title production_title FROM volunteer_hour_entries h LEFT JOIN volunteer_shifts vs ON vs.id=h.shift_id LEFT JOIN productions p ON p.id=h.production_id WHERE h.user_id=:user AND h.status='verified' ORDER BY h.served_at DESC,h.id DESC");$s->execute(['user'=>$uid]);return $s->fetchAll();}
    private static function trainingForUser(PDO $db,int $uid):array{$s=$db->prepare("SELECT m.id,m.title,m.description,m.completion_instructions,vr.name requirement_name,c.status,c.completed_at FROM volunteer_training_modules m LEFT JOIN volunteer_requirements vr ON vr.id=m.requirement_id LEFT JOIN volunteer_training_completions c ON c.module_id=m.id AND c.user_id=:user AND c.status='completed' WHERE m.active=1 ORDER BY c.completed_at IS NULL DESC,m.title");$s->execute(['user'=>$uid]);return $s->fetchAll();}
    private static function requirements(PDO $db):array{return $db->query('SELECT id,name,category,expires FROM volunteer_requirements ORDER BY name')->fetchAll();}
    private static function volunteers(PDO $db):array{return $db->query("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name FROM users u JOIN volunteer_profiles vp ON vp.user_id=u.id AND vp.active=1 WHERE u.active=1 ORDER BY u.last_name,u.first_name")->fetchAll();}
    private static function forms(PDO $db):array{return $db->query('SELECT id,title FROM forms WHERE active=1 ORDER BY title')->fetchAll();}
    private static function modules(PDO $db):array{return $db->query('SELECT id,title FROM volunteer_training_modules WHERE active=1 ORDER BY title')->fetchAll();}
    private static function mappings(PDO $db):array{return $db->query("SELECT frm.form_id,f.title form_title,frm.requirement_id,vr.name requirement_name,frm.validity_days FROM form_requirement_mappings frm JOIN forms f ON f.id=frm.form_id JOIN volunteer_requirements vr ON vr.id=frm.requirement_id WHERE frm.active=1 ORDER BY f.title,vr.name")->fetchAll();}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function flash(string $type,string $message):void{$_SESSION['volunteer_development_flash']=['type'=>$type,'message'=>$message];}
    private static function takeFlash():?array{$f=$_SESSION['volunteer_development_flash']??null;unset($_SESSION['volunteer_development_flash']);return $f;}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);echo 'Restricted';exit;}
}
